(() => {
  'use strict';
  const D=window.BloomData, Engine=window.BloomEngine, FX=window.BloomFX, Art=window.BloomCardArt, Progress=window.BloomProgress;
  const app=document.getElementById('app'),modal=document.getElementById('modal');
  // Share each atlas once, including in the self-contained offline edition.
  for(const [hero,src] of Object.entries({...Art.sources,...Art.evolvedSources})){
    const url=src.startsWith('data:image/png;base64,')?URL.createObjectURL(new Blob([Uint8Array.from(atob(src.slice(src.indexOf(',')+1)),c=>c.charCodeAt(0))],{type:'image/png'})):src;
    document.documentElement.style.setProperty('--cards-'+hero,`url("${url}")`);
  }
  const STORE='bloom-spire.run.v1',SETTINGS='bloom-spire.settings.v1',HISTORY='bloom-spire.history.v1',PROFILE='bloom-spire.progress.v1';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ultimateChoice={};
  let storageOK=true;function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
  function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{if(storageOK)toast('このブラウザーでは自動保存できません。設定から記録を書き出せます。');storageOK=false;}}
  let settings={music:true,sound:true,motion:!matchMedia('(prefers-reduced-motion: reduce)').matches,volume:.35,...read(SETTINGS,{})};
  let engine=new Engine(),saved=read(STORE,null),page='title',heroChoice='knight',difficultyChoice='adventure',selected=null,busy=false,deckFilter='all',viewMode='',toastTimer,cardDrag=null;
  if(saved)try{engine.load(saved);heroChoice=engine.s.hero;}catch{saved=null;}
  let profile=Progress.normalize(read(PROFILE,{})),modeChoice='story',rankChoice=1;for(const past of read(HISTORY,[]))profile=Progress.record(profile,past);if(engine.s)profile=Progress.record(profile,engine.s);
  const icons={
    star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1Z"/>',
    flower:'<path d="M12 8C3-5-5 13 8 12-5 21 13 29 12 16c9 13 17-5 4-4C29 3 11-5 12 8Z"/><circle cx="12" cy="12" r="3"/>',
    sword:'<path d="m14 4 7-1-1 7-9 9-6-6Z M3 15l6 6 M3 21l4-4 M13 11l6-6"/>',
    shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z M8 12l3 3 5-6"/>',
    heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
    energy:'<path d="m13 2-9 12h7l-1 8 10-12h-7Z"/>',
    coin:'<circle cx="12" cy="12" r="9"/><path d="m12 6 4 6-4 6-4-6Z"/>',
    book:'<path d="M3 3h6c2 0 3 2 3 2s1-2 3-2h6v17h-6c-2 0-3 1-3 1s-1-1-3-1H3Z M12 5v16"/>',
    cards:'<rect x="6" y="3" width="14" height="18" rx="2"/><path d="M4 6H2v15h2 M10 8h6 M10 12h6 M10 16h4"/>',
    map:'<path d="m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3Z M8 2v17 M16 5v17"/>',
    settings:'<path d="m9 3-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3Z"/><circle cx="12" cy="11" r="3"/>',
    potion:'<path d="M9 3h6 M10 3v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3 M7 15h10"/>',
    moon:'<path d="M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13Z"/>',
    leaf:'<path d="M20 3S6 1 4 12s12 14 16-9Z M5 20 15 9"/>',
    crown:'<path d="m3 5 4 5 5-7 5 7 4-5-2 14H5Z M5 22h14"/>',
    skull:'<path d="M6 17c-6-9 0-15 6-15s12 6 6 15v5H6Z M9 18v4 M15 18v4"/><circle cx="8" cy="11" r="2"/><circle cx="16" cy="11" r="2"/>',
    fire:'<path d="M12 2c2 8 8 8 8 14a8 8 0 0 1-16 0c0-3 2-6 4-8 0 4 2 4 2 4Z"/>',
    flame:'<path d="M12 2c2 8 8 8 8 14a8 8 0 0 1-16 0c0-3 2-6 4-8 0 4 2 4 2 4Z"/>',
    chest:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M3 12h18 M8 7V3h8v4 M10 11v5h4v-5"/>',
    shop:'<path d="m3 3-2 7c0 3 4 3 5 0 1 3 5 3 6 0 1 3 5 3 6 0 1 3 5 3 5 0l-2-7Z M3 13v8h18v-8 M9 21v-6h6v6"/>',
    question:'<path d="M8 7a4 4 0 0 1 8 0c0 4-4 3-4 7 M12 19v1"/><circle cx="12" cy="12" r="10"/>',
    arrow:'<path d="M4 12h16 M14 6l6 6-6 6"/>',
    close:'<path d="m5 5 14 14 M19 5 5 19"/>',
    check:'<path d="m4 12 5 5L20 6"/>',
    sound:'<path d="m3 9 5 0 5-5v16l-5-5H3Z M17 8c4 4 0 8 0 8 M20 5c7 7 0 14 0 14"/>',
    mute:'<path d="m3 9 5 0 5-5v16l-5-5H3Z M17 9l5 6 M22 9l-5 6"/>',
    feather:'<path d="M20 3c-8-5-17 4-16 14L2 22l5-4c10 0 17-9 13-15Z M5 18 17 6 M10 12l1 5"/>',
    crystal:'<path d="m12 2 8 8-8 12-8-12Z M4 10h16 M12 2v20"/>',
    bell:'<path d="M5 16V9a7 7 0 0 1 14 0v7l2 3H3Z M9 22h6"/>',
    compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-3 5-5 3 3-5Z"/>',
    cup:'<path d="M3 7h14v10a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z M17 8h3a3 3 0 0 1 0 6h-3 M7 2v2 M12 2v2"/>',
    download:'<path d="M12 2v13 M7 10l5 5 5-5 M3 16v6h18v-6"/>',
    chevron:'<path d="m8 4 8 8-8 8"/>',
    history:'<path d="M3 11a9 9 0 1 1 2 7 M3 3v8h8 M12 6v7l4 2"/>'
  };
  function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.star}</svg>`;}
  const rects=[[12,0,337,380],[370,1,362,379],[768,5,288,377],[1110,40,327,338],[16,403,340,312],[381,398,359,307],[771,421,307,292],[1133,375,308,341],[19,719,346,352],[362,709,365,365],[742,700,348,386],[1093,716,349,356]];
  function sprite(i,cls=''){
    if(i>=14)return atlasSprite('./assets/expedition-enemies.png',window.BloomAtlas.enemies.regions[i-14],window.BloomAtlas.enemies.width,window.BloomAtlas.enemies.height,cls);
    const extra=i>=12;
    const [x,y,w,h]=extra?(i===12?[75,185,680,730]:[815,187,654,729]):rects[i];
    return `<svg class="sprite ${cls}" viewBox="0 0 ${w} ${h}" aria-hidden="true"><svg width="${w}" height="${h}" viewBox="${x} ${y} ${w} ${h}" overflow="hidden"><image href="${extra?'./assets/heroes-extra.png':'./assets/character-atlas.png'}" width="${extra?1536:1448}" height="${extra?1024:1086}"/></svg></svg>`;
  }
  const assetURLs=new Map();
  function assetURL(src){if(!src.startsWith('data:image/png;base64,'))return src;if(!assetURLs.has(src))assetURLs.set(src,URL.createObjectURL(new Blob([Uint8Array.from(atob(src.slice(src.indexOf(',')+1)),c=>c.charCodeAt(0))],{type:'image/png'})));return assetURLs.get(src);}
  function atlasSprite(src,rect,width,height,cls=''){src=assetURL(src);const [x,y,r,b]=rect,w=r-x,h=b-y;return `<svg class="sprite ${cls}" viewBox="0 0 ${w} ${h}" aria-hidden="true"><svg width="${w}" height="${h}" viewBox="${x} ${y} ${w} ${h}" overflow="hidden"><image href="${src}" width="${width}" height="${height}"/></svg></svg>`;}
  function heroSprite(hero,costume){const h=D.heroes[hero];costume=costume||(page==='game'&&engine.s?.hero===hero?engine.s.costume:profile.equipped[hero])||'default';if(costume==='default')return sprite(h.sprite);const a=window.BloomAtlas.costumes;return atlasSprite('./assets/costumes.png',a.regions[(costume==='festival'?0:5)+Object.keys(D.heroes).indexOf(hero)],a.width,a.height);}
  const button=(text,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
  const iconButton=(name,action,title,extra='')=>`<button class="icon-btn" data-action="${action}" aria-label="${esc(title)}" title="${esc(title)}" ${extra}>${icon(name)}</button>`;
  const rarityName={basic:'基本',common:'コモン',uncommon:'アンコモン',rare:'レア',curse:'呪い',status:'状態異常'};
  const typeName={attack:'アタック',skill:'スキル',power:'パワー',curse:'呪い',status:'状態異常'};
  function cardHTML(instance,options={}) {
    const visualHero=options.hero||instance.visualHero||(viewMode==='codex'&&deckFilter!=='all'?deckFilter:engine.s?.hero)||heroChoice;
    const c=D.getCard(instance,visualHero),art=Art.get(c.id,visualHero,c.branch);const selectedClass=selected===instance.uid?' selected':'';
    const disabled=options.battle&&(c.cost<0||c.cost>engine.s.battle.energy);
    const action=options.action||(options.battle?'card':'inspect-card');
    let desc=D.describe(instance);

    return `<button class="game-card ${c.type} ${c.rarity}${c.ultimate?' ultimate-card':''}${selectedClass}${disabled?' unplayable':''}${c.upgraded?' upgraded':''}${c.branch?' evolved branch-'+c.branch:''}" data-action="${action}" data-uid="${instance.uid??''}" data-card="${c.id}" data-hero="${visualHero}" data-branch="${c.branch||''}" ${options.battle?'draggable="true"':''} style="${options.style||''}" aria-label="${esc(c.name+'、コスト'+c.cost+'。'+desc)}" ${options.disabled||(options.battle&&busy)?'disabled':''}>
      <span class="card-top"><span class="card-cost">${c.cost<0?'—':c.cost}</span><span class="card-name">${esc(c.name)}</span></span>
      <span class="card-art unique-card-art" data-art-key="${art.key}" style="background-image:var(--cards-${art.hero});background-size:${art.sizeX}% ${art.sizeY}%;background-position:${art.x}% ${art.y}%"></span><span class="card-type">${typeName[c.type]}<span>${c.branch?'✦ '+c.branchName:c.ultimate?'✦ 必殺技':rarityName[c.rarity]}</span></span>
      <span class="card-desc">${esc(desc)}</span><span class="card-foot">${icon(c.type==='attack'?'sword':c.type==='power'?'star':'shield')}<i></i>${c.branch?(c.branch==='power'?'ASCENDED · POWER':'ASCENDED · TECHNIQUE'):c.ultimate?'ULTIMATE ART':c.upgraded?'ENHANCED':'BLOOM SPIRE'}</span>
      ${options.key?`<span class="card-key">${options.key}</span>`:''}
    </button>`;
  }
  function healthBar(hp,max,cls=''){return `<div class="health-bar ${cls}" aria-label="HP ${hp} / ${max}"><span style="width:${Math.max(0,hp/max)*100}%"></span><b>${icon('heart')}${hp}<small>/ ${max}</small></b></div>`;}
  function particles(){return `<div class="fireflies" aria-hidden="true">${Array.from({length:15},(_,i)=>`<i style="--x:${(i*31+7)%100}%;--y:${(i*23+13)%100}%;--delay:${i*-.9}s;--duration:${5+i%5}s"></i>`).join('')}</div>`;}
  function topbar(){const s=engine.s,h=D.heroes[s.hero];return `<header class="topbar"><button class="brand-small" data-action="home-menu" title="メニュー">${icon('flower')}<span>BLOOM <i>SPIRE</i></span></button><div class="hero-summary"><span class="hero-name">${h.name}</span>${healthBar(s.hp,s.maxHP)}<span class="gold">${icon('coin')}<b>${s.gold}</b></span></div><span class="chapter-mini">${s.mode==='ascent'?'試練'+s.rank+' · ':''}STAGE ${s.act+1} <b>${D.actFor(s.act).name}</b><small>${Math.max(0,s.row+1)} / 12</small></span><nav>${iconButton('map','view-map','マップ [M]')}${button(`${icon('cards')}<b>${s.deck.length}</b>`,'deck','nav-deck','title="デッキ [D]"')}${iconButton('settings','settings','設定')}</nav></header><div class="relicbar"><div class="relic-list" aria-label="所持レリック">${s.relics.map(id=>`<button class="relic-token ${D.relics[id].hero?'exclusive':''}" data-action="relic" data-id="${id}" title="${D.relics[id].name}：${D.relics[id].desc}" aria-label="${D.relics[id].name}、${D.relics[id].desc}">${icon(D.relics[id].icon)}<span><b>${D.relics[id].name}</b><small>${D.relics[id].hero?'専用 · ':''}${engine.relicStatus(id)}</small></span></button>`).join('')}</div>${iconButton('chest','relics','レリック一覧と効果')}<div class="potion-list">${[0,1,2].map(i=>s.potions[i]?`<button class="potion" data-action="potion" data-index="${i}" style="--potion:${D.potions[s.potions[i]].color}" title="${D.potions[s.potions[i]].name}" aria-label="${D.potions[s.potions[i]].name}">${icon('potion')}</button>`:`<span class="potion empty" title="空のポーション枠">${icon('potion')}</span>`).join('')}<span class="tiny-label">POTIONS</span></div></div>`;}
  function titleHTML(){const canContinue=saved&&saved.screen!=='result';return `<main class="title-screen"><div class="title-shade"></div>${particles()}<header class="title-nav"><span class="wordmark">${icon('flower')} BLOOM SPIRE</span><div>${iconButton(settings.music?'sound':'mute','toggle-music','BGMのオン・オフ')}${iconButton('settings','settings','設定')}</div></header><div class="title-content"><p class="eyebrow">A DECKBUILDING FAIRYTALE</p><h1>Bloom<span>Spire<span class="title-flower">✦</span></span></h1><div class="title-sub"><i></i>花灯りの塔<i></i></div><p class="title-line">小さな勇気で、夜明けを。</p><div class="title-actions">${canContinue?button(`冒険をつづける ${icon('arrow')}`,'continue','primary'):''}${button(`新しい冒険 ${icon('arrow')}`,'new',canContinue?'secondary':'primary')}${button(`${icon('book')} あそびかた`,'help','text-button')}</div></div><div class="title-party"><div class="orbit-ring"></div><div class="party-member party-witch">${heroSprite('witch')}</div><div class="party-member party-alchemist">${heroSprite('alchemist')}</div><div class="party-member party-dragoon">${heroSprite('dragoon')}</div><div class="party-member party-ranger">${heroSprite('ranger')}</div><div class="party-member party-knight">${heroSprite('knight')}</div><div class="party-caption"><span>✧</span> YOUR LITTLE ADVENTURE AWAITS <span>✧</span></div></div><footer class="title-footer"><span>5人の冒険者。ひとつの夜明け。</span><div>${button('カード図鑑','codex','text-button')}${button('冒険の記録','history','text-button')}${button('衣装と称号','wardrobe','text-button')}<span class="version">v1.2</span></div></footer></main>`;}
  function selectHTML(){const h=D.heroes[heroChoice],chosen=ultimateChoice[h.id]||h.ultimates[0];return `<main class="select-screen expansion-select" style="--hero-color:${h.color}">${particles()}<header class="screen-heading">${button('← もどる','title','text-button')}<div><p class="eyebrow">CHOOSE YOUR ADVENTURER</p><h1>だれと旅に出る？</h1></div><span class="heading-spacer"></span></header>
    <nav class="hero-roster" aria-label="冒険者を選ぶ">${Object.values(D.heroes).map(hero=>`<button class="roster-button ${hero.id===h.id?'active':''}" data-action="select-hero" data-id="${hero.id}" aria-pressed="${hero.id===h.id}" style="--hero-color:${hero.color}"><span class="roster-portrait">${heroSprite(hero.id)}</span><span><b>${hero.name}</b><small>${hero.mechanic}</small></span>${hero.sprite>11?'<i>NEW</i>':''}</button>`).join('')}</nav>
    <div class="adventurer-showcase"><section class="adventurer-detail"><p class="eyebrow">${h.en}</p><div class="adventurer-art">${heroSprite(h.id)}<span class="hero-orbit"></span></div><div class="adventurer-name"><h2>${h.name}</h2><span>${icon('heart')} ${h.hp}</span></div><p class="equipped-title">${Progress.titles(profile).find(t=>t.id===profile.title).name}</p>${button(Progress.costumes[profile.equipped[h.id]].name+' · 衣装変更','wardrobe','wardrobe-link')}<p class="adventurer-role">${h.role}<b>${h.mechanic}</b></p><p class="adventurer-description">${h.description}</p><p class="adventurer-relic" title="${D.relics[h.relic].desc}">${icon(D.relics[h.relic].icon)} ${D.relics[h.relic].name}<small>${D.relics[h.relic].desc}</small></p></section>
    <section class="signature-select"><div class="signature-heading"><p class="eyebrow">YOUR SIGNATURE ART</p><h2>最初の必殺技を選ぶ</h2><p>選んだ1枚をデッキに追加。毎戦闘、最初の手札に入ります。</p></div><div class="signature-options">${h.ultimates.map((id,i)=>{const c=D.cards[id];return `<article class="signature-option ${chosen===id?'active':''}"><button class="signature-pick" data-action="choose-ultimate" data-id="${id}" aria-pressed="${chosen===id}" aria-label="${c.name}を選ぶ"><div class="signature-art">${FX.portrait(h.id,i)}<span class="signature-number">0${i+1}</span><span class="signature-cost">${c.cost}</span></div><div class="signature-copy"><span class="signature-en">${c.ultimate.en}</span><h3>${c.name}</h3><p>${D.describe(id)}</p><span class="signature-state">${chosen===id?'✓ 選択中':'この必殺技を選ぶ'}</span></div></button><button class="signature-preview" data-action="preview-ultimate" data-id="${id}" aria-label="${c.name}の演出を見る">${icon('star')} 演出を見る</button></article>`;}).join('')}</div><p class="signature-note">ほかの必殺技も、冒険中の報酬やショップで手に入ります。</p></section></div>
    ${journeyModeHTML()}<div class="journey-options"><div><span class="option-label">旅の難しさ</span><div class="difficulty-pills">${Object.entries(Engine.DIFFICULTIES).map(([id,d])=>`<button data-action="difficulty" data-id="${id}" class="${difficultyChoice===id?'active':''}" aria-pressed="${difficultyChoice===id}">${d.name}</button>`).join('')}</div><p class="difficulty-desc">${difficultyChoice==='picnic'?'HPが多く、敵もやさしめ。はじめての旅に。':difficultyChoice==='moonlight'?'手強い敵との旅。磨いたデッキを試そう。':'基本の難易度。選択のひとつひとつを楽しもう。'}</p></div><label class="seed-label">旅のシード <small>省略するとランダム</small><input id="seed-input" maxlength="32" placeholder="例：LILY-2026" autocomplete="off"></label>${button(`旅をはじめる ${icon('arrow')}`,'start','primary')}</div></main>`;}

  const nodeIcons={battle:'sword',elite:'skull',boss:'crown',rest:'fire',event:'question',shop:'shop',treasure:'chest'};
  const nodeNames={battle:'戦闘',elite:'エリート',boss:'ボス',rest:'休憩',event:'できごと',shop:'ショップ',treasure:'宝箱'};
  function mapHTML(readonly=false){const s=engine.s;const available=new Set((s.screen==='map'?engine.availableNodes():[]).map(n=>n.id));const nodes=s.map.flat();const x=n=>95+n.lane*180;const y=n=>65+(11-n.row)*79;return `<div class="map-layout ${readonly?'readonly-map':''}"><aside class="map-aside"><p class="eyebrow">ACT ${s.act+1}</p><h1>${D.actFor(s.act).name}</h1><p class="map-line">${D.actFor(s.act).line}</p><div class="map-companion">${heroSprite(s.hero)}</div><p class="equipped-title">${Progress.titles(profile).find(t=>t.id===(s.title||'traveler'))?.name||'花灯りの旅人'}</p><p class="map-quote">「${D.heroes[s.hero].quote}」</p><div class="map-legend">${Object.entries(nodeNames).map(([k,n])=>`<span>${icon(nodeIcons[k])}${n}</span>`).join('')}</div><div class="act-progress">${D.acts.map((a,i)=>`<span class="${i===s.act%5?'current':i<s.act%5?'done':''}">${i+1}<small>${a.name}</small></span>`).join('')}</div></aside><div class="map-panel"><div class="map-panel-heading"><span>${readonly?'冒険の道のり':'次の灯りを選ぶ'}</span><span>${icon('compass')} FLOOR ${Math.max(0,s.row+1)} / 12</span></div><div class="map-scroll"><div class="map-canvas"><svg class="map-lines" viewBox="0 0 550 1010" preserveAspectRatio="none" aria-hidden="true">${nodes.flatMap(n=>n.links.map(l=>{const next=s.map[n.row+1]?.find(a=>a.lane===l);if(!next)return '';const traveled=n.visited&&next.visited;const near=n.row===s.row&&n.lane===s.lane;return `<path class="${traveled?'traveled':near?'next':''}" d="M${x(n)} ${y(n)} C${x(n)} ${y(n)-36},${x(next)} ${y(next)+36},${x(next)} ${y(next)}"/>`;})).join('')}</svg>${nodes.map(n=>`<button class="map-node ${n.kind} ${n.visited?'visited':''} ${available.has(n.id)&&!readonly?'available':''} ${n.row===s.row&&n.lane===s.lane?'current':''}" style="left:${x(n)/550*100}%;top:${y(n)}px" data-action="${readonly?'noop':'node'}" data-id="${n.id}" ${readonly||!available.has(n.id)?'disabled':''} aria-label="${n.row+1}階 ${nodeNames[n.kind]}${available.has(n.id)?' 進むことができます':''}" title="${n.kind==='boss'?D.enemies[D.actFor(s.act).boss].name:nodeNames[n.kind]}">${icon(nodeIcons[n.kind])}${n.visited?'<span class="node-check">✓</span>':''}${n.kind==='boss'?`<span class="boss-label">${D.enemies[D.actFor(s.act).boss].name}</span>`:''}</button>`).join('')}${s.map.map((r,i)=>`<span class="floor-number" style="top:${y(r[0])}px">${String(i+1).padStart(2,'0')}</span>`).join('')}<span class="map-start">✦ 旅のはじまり ✦</span></div></div><div class="map-tip">${icon('star')}休憩では、HPの回復かカードの強化を選べます。</div></div></div>`;}
  function statusHTML(status){const keys=Object.keys(D.statusLabels).filter(k=>status[k]);return `<div class="status-row">${keys.map(k=>`<span class="status-chip ${k}" title="${D.statusLabels[k][0]}：${D.statusLabels[k][1]}">${icon({bloom:'flower',strength:'sword',dexterity:'feather',poison:'leaf',frost:'crystal',weak:'feather',vulnerable:'shield',thorns:'flower',regen:'heart'}[k]||'star')}<b>${typeof status[k]==='boolean'?'':status[k]}</b><span>${D.statusLabels[k][0]}</span></span>`).join('')}</div>`;}
  function intentHTML(e){const a=engine.intent(e);let name='',mark='',kind=a.kind;
    if(a.kind==='stun')return `<div class="enemy-intent stunned"><span class="intent-caption">次の行動</span><b>✓ ${a.label}</b><small>行動を中断</small></div>`;
    if(a.damage!==undefined){name=`${a.damage}${a.hits>1?' × '+a.hits:''}`;mark='sword';if(a.status)name+=' +';}else if(a.block){name=String(a.block);mark='shield';}else {name='＋'+a.strength;mark='star';}
    const title=(a.damage!==undefined?`${a.damage}ダメージ${a.hits>1?'を'+a.hits+'回':''}`:a.block?`${a.block}ブロック`:`筋力＋${a.strength}`)+(a.status?`、${a.status==='dazed'?'まどろみを捨て札に':D.statusLabels[a.status][0]}${a.amount}`:'');
    return `<div class="enemy-intent ${kind}" title="次の行動：${title}"><span class="intent-caption">次の行動</span><span>${icon(mark)}<b>${name}</b></span><small>${a.status?(a.status==='dazed'?'状態異常':D.statusLabels[a.status][0]):a.block?'まもり':a.strength?'強化':'攻撃'}</small></div>`;
  }
  function battleHTML(){const s=engine.s,b=s.battle,h=D.heroes[s.hero],enemies=b.enemies;const targetable=selected&&engine.needsTarget(b.hand.find(c=>c.uid===selected)||'guard');return `<main class="battle-screen ${targetable?'targeting':''}"><div class="battle-heading"><span class="chapter-en">${D.actFor(s.act).en}</span><h1>${b.kind==='boss'?D.enemies[D.actFor(s.act).boss].name:b.kind==='elite'?'聖域の番人':D.actFor(s.act).name+'の出会い'}</h1><span class="turn-label">TURN <b>${String(b.turn).padStart(2,'0')}</b></span></div>${bossRulesHTML()}<div class="battle-stage"><div class="combatant player" data-entity="player" data-action="play-self"><div class="hero-aura"></div><div class="combat-sprite">${heroSprite(h.id)}</div><div class="combat-name">${h.name}<span>${h.role}</span></div><div class="combat-health">${b.block?`<span class="block-badge">${icon('shield')}${b.block}</span>`:''}${healthBar(s.hp,s.maxHP)}</div>${statusHTML(b.p)}</div><div class="enemies count-${enemies.length}">${enemies.map(e=>`<button class="combatant enemy ${e.hp<=0?'defeated':''} ${e.boss?'boss-enemy':''} ${e.elite?'elite-enemy':''}" data-action="target" data-id="${e.uid}" data-entity="${e.uid}" aria-label="${esc(e.name)} HP ${e.hp} / ${e.maxHP}、${targetable?'カードの対象にする':'敵の情報'}" ${e.hp<=0||busy?'disabled':''}>${e.hp>0?intentHTML(e):''}<div class="combat-sprite ${D.enemies[e.id].tint||''}">${sprite(e.sprite)}</div><div class="combat-name">${e.enraged?icon('flame'):''}${esc(e.name)}</div><div class="combat-health">${e.block?`<span class="block-badge">${icon('shield')}${e.block}</span>`:''}${healthBar(e.hp,e.maxHP,'enemy-health')}</div>${statusHTML(e)}<span class="target-forecast" data-forecast="${e.uid}"></span></button>`).join('')}</div></div><div class="battle-prompt" aria-live="polite">${selected?`${D.getCard(b.hand.find(c=>c.uid===selected)||'guard',s.hero).name} <span>対象の敵を選択</span> ${button('キャンセル [Esc]','cancel-card','text-button')}`:`${icon('star')} カードを選んで、きみの一手を。`}</div><div class="forecast-panel" id="damage-forecast" aria-live="polite">${icon('compass')} カードに触れると、ダメージと効果を予測</div><section class="hand-area" aria-label="手札"><div class="energy-panel"><div class="energy-orb">${icon('energy')}<b>${b.energy}<small>/ ${b.maxEnergy}</small></b></div><span>エナジー</span><small>毎ターン回復</small></div><div class="hand ${b.hand.length>6?'many-cards':''}" style="--count:${b.hand.length}">${b.hand.map((c,i)=>cardHTML(c,{battle:true,key:i<9?i+1:'',style:`--tilt:${(i-(b.hand.length-1)/2)*2.1}deg;--lift:${Math.abs(i-(b.hand.length-1)/2)*3}px;--order:${i};`})).join('')}${!b.hand.length?'<div class="empty-hand">手札がありません。<br>ターンを終了してカードを引きましょう。</div>':''}</div><div class="turn-actions">${button(`ターン終了 ${icon('arrow')}`,'end-turn','end-turn',busy?'disabled':'')}<span>[ Space ]</span></div></section><footer class="battle-footer"><button class="pile draw-pile" data-action="pile" data-id="draw">${icon('cards')}<span>山札</span><b>${b.draw.length}</b></button><button class="log-button" data-action="log">${icon('history')} 戦闘ログ</button><p>カードを選択 → 敵を選択 <span>／</span> ドラッグでも使用できます</p><button class="pile exhaust-pile" data-action="pile" data-id="exhaust">廃棄 <b>${b.exhaust.length}</b></button><button class="pile discard-pile" data-action="pile" data-id="discard">${icon('cards')}<span>捨て札</span><b>${b.discard.length}</b></button></footer></main>`;}
  function rewardHTML(){const r=engine.s.reward;return `<main class="room-screen reward-screen"><div class="room-heading"><span class="victory-seal">${icon('sword')}</span><p class="eyebrow">A LITTLE VICTORY</p><h1>ひとつ、強くなった。</h1><p>旅に連れていくカードを、1枚選びましょう。</p></div><div class="reward-loot"><span class="loot-pill">${icon('coin')}＋${r.gold} <small>獲得済み</small></span>${r.relic?button(`${icon(D.relics[r.relic].icon)} ${D.relics[r.relic].name}${r.relicClaimed?' ✓':''}`,'claim-relic','loot-pill',r.relicClaimed?'disabled':''):''}${r.potion?button(`${icon('potion')}${D.potions[r.potion].name}${r.potionClaimed?' ✓':''}`,'claim-potion','loot-pill',r.potionClaimed?'disabled':''):''}</div><div class="reward-cards">${r.cards.map(c=>`<div class="reward-card-wrap ${r.cardClaimed&&r.chosen!==c.uid?'unchosen':''}">${cardHTML(c,{action:'reward-card',disabled:r.cardClaimed})}<span class="reward-choice">${r.chosen===c.uid?icon('check')+' デッキに追加':r.cardClaimed?'':rarityName[D.cards[c.id].rarity]}</span></div>`).join('')}</div>${button(`${r.cardClaimed?'先へ進む':'カードを選ばず進む'} ${icon('arrow')}`,'finish-reward',r.cardClaimed?'primary':'secondary')}<p class="room-footnote">少数精鋭のデッキも、旅を進めるひとつの方法。</p></main>`;}
  function restHTML(){const s=engine.s;return `<main class="room-screen rest-screen"><div class="room-heading"><span class="room-seal">${icon('fire')}</span><p class="eyebrow">A QUIET MOMENT</p><h1>花灯りの休息</h1><p>あたたかい灯りに包まれて。少しだけ、ひと休み。</p></div><div class="rest-scene">${heroSprite(s.hero)}</div><div class="room-options"><button class="choice-panel" data-action="rest"><span>${icon('heart')}</span><h2>ひと休み</h2><p>HPを${Math.round(s.maxHP*(.3+(engine.has('teacup')?.15:0)))}回復</p><small>いまのHP ${s.hp} / ${s.maxHP}</small></button><button class="choice-panel" data-action="upgrade"><span>${icon('star')}</span><h2>カードを磨く</h2><p>未強化 → ＋ → 分岐進化</p><small>＋のカードは2つの進化先から選択</small></button></div></main>`;}
  function treasureHTML(){const r=engine.s.room;return `<main class="room-screen treasure-screen"><div class="room-heading"><p class="eyebrow">A GIFT FROM THE FOREST</p><h1>森からの贈りもの</h1><p>古い宝箱の中で、小さな魔法が待っていた。</p></div><div class="treasure-relic">${icon(r.relic?D.relics[r.relic].icon:'coin')}</div><h2>${r.relic?D.relics[r.relic].name:'星くずの宝物'}</h2><p class="relic-description">${r.relic?D.relics[r.relic].desc:'レリックはすべて集めました。'}</p><span class="gold reward-gold">${icon('coin')} ＋${r.gold}</span>${button(`受け取って進む ${icon('arrow')}`,'treasure','primary')}</main>`;}
  function bossRewardHTML(){return `<main class="room-screen"><div class="room-heading"><span class="victory-seal">${icon('crown')}</span><p class="eyebrow">THE NEXT CHAPTER</p><h1>新しい力と、その先へ。</h1><p>レリックを1つ選択。次の章へ進むと、最大HPの40%を回復します。</p></div><div class="boss-relics">${engine.s.room.relics.map(id=>`<button class="choice-panel" data-action="boss-relic" data-id="${id}"><span>${icon(D.relics[id].icon)}</span><h2>${D.relics[id].name}</h2>${D.relics[id].hero?'<b class="exclusive-label">'+D.heroes[D.relics[id].hero].name+'専用</b>':''}<p>${D.relics[id].desc}</p><small>選んで次の章へ ${icon('arrow')}</small></button>`).join('')}</div>${button('選ばずに次の章へ','boss-relic','text-button','data-id=""')}${engine.s.mode==='ascent'?button('記録を残して帰還','retire','secondary'):''}</main>`;}
  function eventHTML(){const r=engine.s.room,e=D.events.find(e=>e.id===r.event);return `<main class="room-screen event-screen"><div class="event-illustration"><div class="event-orbit">${icon(e.icon)}</div><span>✧</span></div><div class="event-copy"><p class="eyebrow">A SMALL ENCOUNTER</p><h1>${e.title}</h1><p class="event-story">${e.text}</p>${r.done?`<p class="event-result">${esc(r.result)}</p>${button(`道を進む ${icon('arrow')}`,'leave-room','primary')}`:r.removing?button('手放すカードを選ぶ','event-remove','primary'):`<div class="event-options">${e.options.map((o,i)=>`<button data-action="event-choice" data-index="${i}" ${o.cost>engine.s.gold||(['labor','rare','sacrifice'].includes(o.effect)&&engine.s.hp<=o.value)?'disabled':''}><span>${o.label}<small>${o.detail}</small></span>${icon('chevron')}</button>`).join('')}</div>`}</div></main>`;}
  function shopHTML(){const s=engine.s,r=s.room;return `<main class="shop-screen"><div class="shop-heading"><div><p class="eyebrow">THE FIREFLY EMPORIUM</p><h1>ほたるの雑貨店</h1><p>「とっておきを、取り揃えております。」</p></div><div>${button(`旅にもどる ${icon('arrow')}`,'leave-room','secondary')}</div></div><div class="shop-shelf cards-shelf">${r.cards.map((c,i)=>`<div class="shop-item ${c.sold?'sold':''}">${cardHTML(c,{action:'shop-preview',disabled:c.sold})}${button(c.sold?'SOLD OUT':`${icon('coin')} ${c.price}${i===0?' <small>SALE</small>':''}`,'buy','price',`data-kind="cards" data-index="${i}" ${c.sold||s.gold<c.price?'disabled':''}`)}</div>`).join('')}</div><div class="shop-bottom"><div class="shop-trinkets">${r.relics.map((r,i)=>`<button class="shop-trinket ${r.sold?'sold':''}" data-action="buy" data-kind="relics" data-index="${i}" ${r.sold||s.gold<r.price?'disabled':''} title="${D.relics[r.id].desc}"><span>${icon(D.relics[r.id].icon)}</span><div><b>${D.relics[r.id].name}</b><p>${D.relics[r.id].desc}</p><small>${r.sold?'売り切れ':icon('coin')+r.price}</small></div></button>`).join('')}${r.potions.map((p,i)=>`<button class="shop-trinket potion-trinket ${p.sold?'sold':''}" data-action="buy" data-kind="potions" data-index="${i}" ${p.sold||s.gold<p.price?'disabled':''}><span>${icon('potion')}</span><div><b>${D.potions[p.id].name}</b><p>${D.potions[p.id].desc}</p><small>${p.sold?'売り切れ':icon('coin')+p.price}</small></div></button>`).join('')}</div><button class="remove-service" data-action="shop-remove" ${r.removed||s.gold<65?'disabled':''}>${icon('cards')}<h3>思い出を手放す</h3><p>カードを1枚削除する</p><b>${r.removed?'利用済み':icon('coin')+' 65'}</b></button></div></main>`;}
  function resultHTML(){const s=engine.s;const minutes=Math.max(1,Math.round(((s.endedAt||Date.now())-s.startedAt)/60000));return `<main class="room-screen result-screen ${s.won?'won':''}">${particles()}<div class="result-character">${heroSprite(s.hero)}</div><div class="result-copy"><p class="eyebrow">${s.won?'AND THE FLOWERS BLOOM AGAIN':'EVERY JOURNEY LEAVES A LIGHT'}</p><h1>${s.won?'きみが、夜明けを連れてきた。':s.retired?'星の記録と、帰り道。':'また、花の咲く日に。'}</h1><p>${s.won?'花灯りの塔に、あたたかな朝が戻りました。':'この旅の思い出は、次の冒険への道しるべ。'}</p><div class="result-stats"><div><b>${s.stats.floors}<small>${s.mode==='ascent'?'階':'/ 60'}</small></b><span>進んだ階</span></div><div><b>${s.stats.battles}</b><span>勝った戦闘</span></div><div><b>${s.deck.length}</b><span>デッキの枚数</span></div><div><b>${minutes}<small>分</small></b><span>冒険の時間</span></div></div><p class="result-seed">${D.heroes[s.hero].name} · ${Engine.DIFFICULTIES[s.difficulty].name} · SEED ${esc(s.seed)}</p>${resultProgressHTML()}<div class="result-actions">${button(`もう一度、冒険へ ${icon('arrow')}`,'new','primary')}${button('最後のデッキを見る','deck','secondary')}${button('タイトルへ','title','text-button')}</div></div></main>`;}
  function render(){
    document.documentElement.classList.toggle('reduced-motion',!settings.motion);
    const s=engine.s;document.body.dataset.theme=s&&page==='game'?D.actFor(s.act).theme:'forest';
    if(page==='title')app.innerHTML=titleHTML();else if(page==='select')app.innerHTML=selectHTML();else{const screens={map:()=>mapHTML(),battle:battleHTML,reward:rewardHTML,rest:restHTML,treasure:treasureHTML,event:eventHTML,shop:shopHTML,bossReward:bossRewardHTML,result:resultHTML};app.innerHTML=`<div class="game-shell ${s.screen}-shell">${topbar()}${screens[s.screen]()}</div>`;}
    app.classList.toggle('busy',busy);if(page==='game'&&s.screen==='battle'&&selected)updateForecast(selected);
    if(page==='game'&&s.screen==='map')requestAnimationFrame(()=>{const wrap=app.querySelector('.map-scroll');const next=app.querySelector('.map-node.available');if(wrap&&next)wrap.scrollTop=Math.max(0,parseFloat(next.style.top)-wrap.clientHeight*.67);});
  }
  function save(){if(!engine.s)return;profile=Progress.record(profile,engine.s);write(PROFILE,profile);saved=JSON.parse(engine.serialize());write(STORE,saved);if(engine.s.screen==='result'){const history=read(HISTORY,[]);if(!history.some(r=>r.startedAt===saved.startedAt)){history.unshift({...saved,deck:cloneDeck(saved.deck),battle:null,map:[],room:null,reward:null});write(HISTORY,history.slice(0,20));}}}
  const cloneDeck=deck=>deck.map(c=>({...c}));
  function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3200);}
  function showModal(title,body,cls=''){modal.className=cls;modal.innerHTML=`<div class="modal-header"><h2>${title}</h2>${iconButton('close','close','閉じる')}</div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
  function closeModal(){modal.close();viewMode='';}
  function announce(text){document.getElementById('announcer').textContent=text;}
  function applyFx(effects){const layer=document.getElementById('fx');const grouped=new Map();for(const e of effects){const target=document.querySelector(`[data-entity="${e.target}"]`);if(!target)continue;const rect=target.getBoundingClientRect();if(['damage','poison','heal','block','buff','status'].includes(e.type)){const n=grouped.get(e.target)||0;grouped.set(e.target,n+1);const pop=document.createElement('span');pop.className=`damage-number fx-${e.type}`;pop.style.left=`${rect.left+rect.width*.5+(n%3-1)*25}px`;pop.style.top=`${rect.top+rect.height*.38-(Math.floor(n/3)*24)}px`;pop.style.animationDelay=`${n*.09}s`;pop.textContent=(e.type==='heal'?'+':'')+(e.label&&e.type==='status'?e.label+' ':'')+e.value;layer.appendChild(pop);setTimeout(()=>pop.remove(),1400+n*90);if(e.type==='damage'||e.type==='poison'){target.classList.remove('hit');void target.offsetWidth;target.classList.add('hit');}if(e.type==='block')target.classList.add('shielded');}if(e.type==='defeat')target.classList.add('vanishing');}
    if(effects.some(e=>e.type==='victory'))Sound.chime();else if(effects.some(e=>e.type==='damage'))Sound.hit();else if(effects.some(e=>e.type==='block'))Sound.block();else Sound.click();
  }
  async function perform(fn,animated=false){
    if(busy)return;let locked=false;
    try{
      const prior=engine.s?.screen;fn();selected=null;save();const effects=engine.takeFx();
      if(animated&&prior==='battle'){
        busy=true;locked=true;app.inert=true;app.classList.add('busy');
        const opener=effects.find(e=>e.type==='card');
        const prompt=app.querySelector('.battle-prompt');if(prompt)prompt.textContent=opener?`${opener.label}！`:'敵のターン';
        const used=opener&&app.querySelector(`.hand [data-uid="${opener.cardUid}"]`);if(used)used.classList.add('card-playing');
        await FX.play(effects,{hero:engine.s.hero,motion:settings.motion,sound:Sound,announce});
        if(engine.s.screen!=='battle')announce(engine.s.screen==='result'?(engine.s.won?'塔をクリアしました。':'冒険が終わりました。'):'戦闘に勝利しました。報酬を選んでください。');
      }else{render();applyFx(effects);}return true;
    }catch(error){toast(error.message);Sound.error();return false;}
    finally{if(locked){busy=false;app.inert=false;render();}}
  }
  async function previewUltimate(id,branch,hero){
    if(busy)return;const seed=document.getElementById('seed-input')?.value,focusBefore=document.activeElement,restore=modal.open?{html:modal.innerHTML,cls:modal.className}:null;closeModal();busy=true;app.inert=true;
    try{await FX.preview(id,{motion:settings.motion,sound:Sound,announce,branch,hero:hero||heroChoice});}finally{busy=false;app.inert=false;if(restore){modal.className=restore.cls;modal.innerHTML=restore.html;modal.showModal();}if(focusBefore?.isConnected)focusBefore.focus({preventScroll:true});if(page==='select'&&document.getElementById('seed-input'))document.getElementById('seed-input').value=seed||'';}
  }
  function cardSelect(uid){if(busy)return;uid=Number(uid);const c=engine.s.battle.hand.find(c=>c.uid===uid);if(!c)return;const card=D.getCard(c);if(card.cost<0||card.cost>engine.s.battle.energy){toast(card.cost<0?'このカードはプレイできません。':'エナジーが足りません。');Sound.error();return;}if(engine.needsTarget(c)){selected=selected===uid?null:uid;Sound.click();render();}else perform(()=>engine.play(uid),true);}
  function help(){showModal('冒険のしおり',`<div class="help-intro">${icon('flower')}小さな選択を重ねて、5つのステージの先にある塔へ。</div><div class="help-grid"><section><b>01</b><h3>道を選ぶ</h3><p>マップの光っている場所へ進みます。戦闘、休憩、ショップ、できごと。12階のボスを倒すと次の章へ。</p></section><section><b>02</b><h3>カードで戦う</h3><p>毎ターン、基本5枚を引き、3エナジーが回復。攻撃カードを選んで敵を選択。防御カードはクリックで使用できます。</p></section><section><b>03</b><h3>敵の予告を見る</h3><p>敵の頭上に次の行動が表示されます。攻撃はブロックで防御。自分のブロックは、次のターン開始時に消えます。</p></section><section><b>04</b><h3>デッキを育てる</h3><p>勝つと3枚から1枚を選べます。スキップも可能。休憩で「通常 → ＋ → 2つの分岐」の順に強化。進化すると絵と演出も変わります。</p></section></div><p class="ultimate-help">✦ 必殺技は1人につき3種類。最初に1枚選び、ほかの技は報酬やショップで獲得できます。演出は［Esc］でスキップ、設定で省略できます。</p><h3>夜明けの、その先へ</h3><p class="muted">物語の5ステージをクリアすると「星巡りの踏破」と、そのキャラの衣装が解放。踏破では5ステージごとに敵が強くなり、試練は10段階。記録を伸ばして衣装と称号を集めましょう。</p><h3>旅のキーワード</h3><div class="glossary">${Object.entries(D.statusLabels).map(([k,[n,d]])=>`<div><b>${n}</b><p>${d}</p></div>`).join('')}<div><b>廃棄</b><p>その戦闘では使えなくなります。次の戦闘でデッキに戻ります。パワーカードも使用後は廃棄されます。</p></div><div><b>山札・手札・捨て札</b><p>ターン終了で手札を捨てます。山札がなくなったら、捨て札をシャッフル。手札の上限は10枚です。</p></div></div><div class="keyboard-help"><span><kbd>1–9</kbd> カード選択</span><span><kbd>Space</kbd> ターン終了</span><span><kbd>Esc</kbd> キャンセル</span><span><kbd>D</kbd> デッキ</span><span><kbd>M</kbd> マップ</span></div><p class="muted">冒険はこのブラウザーに自動保存されます。設定から記録を書き出して、別の端末へ移せます。</p>`,'wide-modal');}
  function deckModal(mode='deck',pile){viewMode=mode;const s=engine.s;let list=mode==='codex'?Object.keys(D.cards).filter(id=>!['curse','status'].includes(D.cards[id].type)).flatMap((id,i)=>['strike','guard'].includes(id)?Object.keys(D.heroes).map((h,j)=>({id,uid:100000+i*5+j,upgraded:false,visualHero:h})):[{id,uid:100000+i*5,upgraded:false}]):pile?s.battle[pile]:s.deck;
    if(mode==='upgrade')list=list.filter(c=>D.upgradeLevel(c)<2&&!['curse','status'].includes(D.cards[c.id].type));
    if(mode==='codex'&&deckFilter!=='all')list=list.filter(c=>c.visualHero?c.visualHero===deckFilter:D.cards[c.id].hero===deckFilter||D.cards[c.id].hero==='all');
    if(pile==='draw')list=list.slice().sort((a,b)=>a.id.localeCompare(b.id));
    const titles={deck:`あなたのデッキ · ${list.length}枚`,upgrade:'強化するカードを選ぶ',remove:'削除するカードを選ぶ',codex:'カード図鑑'};
    showModal(pile?{draw:'山札（順不同）',discard:'捨て札',exhaust:'廃棄したカード'}[pile]:titles[mode],`${mode==='upgrade'?'<p class="modal-note">未強化カードは＋の性能を表示。＋のカードを選ぶと、2つの進化先を比較できます。最終進化したカードは対象外です。</p>':''}${mode==='remove'?'<p class="modal-note">カードを選択すると削除を確認できます。</p>':''}${mode==='codex'?`<div class="filter-pills">${[['all','すべて'],...Object.values(D.heroes).map(h=>[h.id,h.name])].map(([id,name])=>button(name,'filter',deckFilter===id?'active':'',`data-id="${id}"`)).join('')}</div>`:''}<div class="card-grid">${list.map(c=>cardHTML(mode==='upgrade'?{...c,upgraded:true}:c,{action:mode==='upgrade'?'upgrade-card':mode==='remove'?'remove-confirm':'inspect-card'})).join('')}</div>${!list.length?'<p class="empty-message">ここにカードはありません。</p>':''}`,'wide-modal');}
  function settingsModal(){showModal('設定',`<div class="settings-list"><label><span>BGM<small>星空のアンビエント</small></span><input type="checkbox" data-setting="music" ${settings.music?'checked':''}></label><label><span>効果音</span><input type="checkbox" data-setting="sound" ${settings.sound?'checked':''}></label><label><span>アニメーション<small>必殺技のカットインと戦闘演出</small></span><input type="checkbox" data-setting="motion" ${settings.motion?'checked':''}></label><label><span>音量</span><input type="range" min="0" max="1" step=".05" value="${settings.volume}" data-setting="volume" aria-label="音量"></label></div><div class="settings-actions">${button(`${icon('book')} あそびかた`,'help','secondary')}${engine.s?button(`${icon('download')} 冒険の記録を書き出す`,'export','secondary'):''}<label class="btn secondary import-label">記録を読み込む<input type="file" id="import-save" accept="application/json,.json"></label>${page==='game'?button('保存してタイトルへ','save-title','text-button'):''}</div><p class="muted">自動保存は端末・ブラウザーごと。音楽はクリック後に再生されます。</p>`);}
  function potionModal(index){const id=engine.s.potions[index];if(!id)return;showModal(D.potions[id].name,`<div class="item-modal-icon">${icon('potion')}</div><p>${D.potions[id].desc}${id==='heal'&&engine.has('vial')?' 小瓶の効果でさらに8回復。':''}</p><div class="modal-actions">${button('使う','use-potion','primary',`data-index="${index}" ${id!=='heal'&&engine.s.screen!=='battle'?'disabled':''}`)}${button('捨てる','discard-potion','secondary',`data-index="${index}"`)}</div>${id!=='heal'&&engine.s.screen!=='battle'?'<p class="muted">戦闘中に使えます。</p>':''}`);}
  function inspectCard(el){const uid=Number(el.dataset.uid),id=el.dataset.card;let c=engine.s?.deck.find(c=>c.uid===uid&&c.id===id)||engine.s?.battle?.hand.find(c=>c.uid===uid&&c.id===id)||{id,upgraded:false};c={...c,visualHero:el.dataset.hero||engine.s?.hero||heroChoice};const evolves=!['curse','status'].includes(D.cards[id].type);showModal(D.getCard(c).name,`<p class="modal-note">通常 → ＋ → 2つの最終進化。分岐すると専用イラストと演出に変わります。</p><div class="inspect-cards">${cardHTML({...c,upgraded:false,branch:null},{action:'noop'})}${evolves?cardHTML({...c,upgraded:true,branch:null},{action:'noop'}):''}</div>${evolves?branchChoicesHTML(c,false):''}`,'wide-modal');}
  function journeyModeHTML(){const open=Progress.ascentUnlocked(profile);return `<section class="journey-mode"><div><p class="eyebrow">BEYOND THE DAWN</p><h3>物語の先にも、旅は続く。</h3><p>5ステージをクリアすると、果てのない踏破と段階的な試練が解放。</p></div><div class="mode-options">${button('物語 · 全5ステージ','journey-mode',modeChoice==='story'?'active':'','data-id="story"')}${button(open?'星巡りの踏破':'踏破解放まで · 5ステージクリア','journey-mode',modeChoice==='ascent'?'active':'',`data-id="ascent" ${open?'':'disabled'}`)}${modeChoice==='ascent'?`<label>試練<select id="ascent-rank" aria-label="試練の段階">${Array.from({length:Progress.maxRank(profile)},(_,i)=>`<option value="${i+1}" ${rankChoice===i+1?'selected':''}>試練 ${i+1} / 10</option>`).join('')}</select></label><p>この試練で5ステージをクリアすると次の段階が解放。5ステージごとに敵がさらに強化され、記録は続きます。</p>`:''}</div></section>`;}
  function branchChoicesHTML(c,choosing){const hero=c.visualHero||engine.s?.hero||heroChoice;return `<div class="branch-choices">${Object.values(D.branches(c.id,hero)).map(b=>`<article class="branch-choice branch-${b.id}"><span class="eyebrow">${b.id==='power'?'POWER EVOLUTION':'TECHNIQUE EVOLUTION'}</span><h3>${b.name}</h3><p>${b.subtitle}</p>${cardHTML({...c,visualHero:hero,upgraded:true,branch:b.id},{action:'noop'})}<div>${button('演出を見る','preview-ultimate','text-button',`data-id="${c.id}" data-branch="${b.id}" data-hero="${hero}"`)}${choosing?button('この分岐へ進化','evolve-card','primary',`data-uid="${c.uid}" data-branch="${b.id}"`):''}</div></article>`).join('')}</div>${choosing?'<p class="modal-note">選択すると休憩を使い、カードが最終進化します。分岐はこの冒険中、変更できません。</p>':''}`;}
  function wardrobeModal(){const h=heroChoice,r=profile.heroes[h];showModal('旅の勲章 · 衣装と称号',`<div class="filter-pills">${Object.values(D.heroes).map(a=>button(a.name,'cosmetic-hero',h===a.id?'active':'',`data-id="${a.id}"`)).join('')}</div><div class="progress-summary"><span>物語 <b>${r.storyBest} / 5</b></span><span>踏破クリア <b>${r.ascentBest} STAGE</b></span><span>最高到達 <b>STAGE ${r.reached}</b></span><span>試練クリア <b>${r.rankCleared} / 10</b></span></div><p class="modal-note">衣装は次の冒険から、探索・戦闘の立ち絵に反映されます。能力は変わりません。</p><div class="wardrobe-grid">${Object.entries(Progress.costumes).map(([id,c])=>{const open=Progress.unlocked(profile,h,id);return `<article class="costume-card ${open?'':'locked'} ${profile.equipped[h]===id?'equipped':''}"><div>${heroSprite(h,id)}</div><h3>${c.name}</h3><p>${c.requirement}</p>${button(open?(profile.equipped[h]===id?'✓ 選択中':'この衣装を選ぶ'):'未解放','equip-costume',open?'secondary':'',`data-id="${id}" ${open?'':'disabled'}`)}</article>`;}).join('')}</div><h3 class="titles-heading">冒険に添える称号</h3><div class="title-collection">${Progress.titles(profile).map(t=>`<button data-action="equip-title" data-id="${t.id}" ${t.unlocked?'':'disabled'} class="${profile.title===t.id?'active':''}"><b>${t.unlocked?'✦':'◇'} ${t.name}${profile.title===t.id?' ✓':''}</b><span>${t.requirement}</span></button>`).join('')}</div>`,'wide-modal');}
  function resultProgressHTML(){const s=engine.s,r=profile.heroes[s.hero];return `<div class="result-progress"><p>到達 <b>STAGE ${s.act+1}</b> · ${s.clearedStages??s.act}ステージ制覇 ${s.mode==='ascent'?' · 試練'+s.rank:''}</p>${s.won&&s.act===4?'<p>✦ 星巡りの踏破と「星祭りの礼装」が解放されました。</p>':''}${s.mode==='ascent'&&(s.clearedStages||0)>=5?`<p>✦ 「暁の継承者」解放。次に選べる試練：${Progress.maxRank(profile)} / 10</p>`:''}<p>このキャラの踏破記録：${r.ascentBest}ステージ制覇</p>${button('衣装・称号と解放条件','wardrobe','secondary')}</div>`;}
  function relicsModal(){showModal('所持レリックと効果',`<div class="relic-collection">${engine.s.relics.map(id=>{const r=D.relics[id];return `<article class="${r.hero?'exclusive':''}"><span>${icon(r.icon)}</span><div><h3>${r.name} ${r.hero?'<small>'+D.heroes[r.hero].name+'専用</small>':''}</h3><p>${r.desc}</p><b>${engine.relicStatus(id)}</b></div></article>`;}).join('')}</div>`,'wide-modal');}
  function bossRulesHTML(){return engine.s.battle.enemies.filter(e=>e.hp>0&&e.boss).map(e=>{const m=engine.bossMechanic(e);return m?`<aside class="boss-rule"><span>${icon('crown')}<b>${m.name}</b><strong>${m.progress}</strong></span><p>${m.description}</p></aside>`:'';}).join('');}
  function updateForecast(uid,targetUid){if(page!=='game'||engine.s?.screen!=='battle'||busy)return;const b=engine.s.battle,c=b.hand.find(c=>c.uid===Number(uid)),panel=document.getElementById('damage-forecast');if(!panel||!c)return;const alive=b.enemies.filter(e=>e.hp>0),target=alive.find(e=>e.uid===targetUid)||alive[0],preview=engine.previewCard(c.uid,target?.uid);if(!preview)return;for(const el of document.querySelectorAll('[data-forecast]'))el.textContent='';if(preview.error){panel.innerHTML=`${icon('compass')} ${esc(preview.error)}`;return;}
    const needs=engine.needsTarget(c);for(const enemy of alive){const own=needs?engine.previewCard(c.uid,enemy.uid):preview,hit=own?.enemies?.find(e=>e.uid===enemy.uid),el=document.querySelector(`[data-forecast="${enemy.uid}"]`);if(hit&&el&&(hit.damage||hit.blocked||hit.poison||hit.frost||hit.reduced))el.textContent=`予測 ${hit.damage}ダメージ · HP ${hit.hp}${hit.hp===0?' 撃破':''}`;}
    const relevant=preview.enemies.filter(e=>e.damage||e.blocked||e.poison||e.frost||e.reduced),breakdown=engine.damageBreakdown(c.uid,target);panel.innerHTML=`<span class="forecast-title">${icon('compass')} ${D.getCard(c,engine.s.hero).name}</span><div class="forecast-results">${relevant.map(e=>`<span><b>${e.name} ${e.hits.length>1?'['+e.hits.join('＋')+']':''} → ${e.damage}ダメージ</b>${e.blocked||e.reduced?`<small>ブロック ${e.blocked} / 固有軽減 ${e.reduced}</small>`:''}${e.poison?`<small>毒 ＋${e.poison}（行動前）</small>`:''}${e.frost?`<small>氷結 ＋${e.frost}</small>`:''}${e.intent.kind==='stun'?'<small>✓ 大技を中断</small>':''}</span>`).join('')}${preview.block?`<b>ブロック ＋${preview.block}</b>`:''}${preview.heal?`<b>回復 ＋${preview.heal}</b>`:''}${!relevant.length&&!preview.block&&!preview.heal?`<span>${D.describe(c)}</span>`:''}</div>${breakdown.length?`<small class="forecast-breakdown">各ヒットの計算要素：${breakdown.map(([n,v])=>n+' '+v).join(' · ')}${preview.relics.length?' · '+preview.relics.join(' / '):''}</small>`:''}`;
  }
  document.addEventListener('pointerover',e=>{const card=e.target.closest('.hand [data-uid]');if(card&&!selected)updateForecast(card.dataset.uid);const enemy=e.target.closest('[data-entity^="enemy"]');if(enemy&&selected)updateForecast(selected,enemy.dataset.entity);});
  document.addEventListener('focusin',e=>{if(e.target.matches('.hand [data-uid]'))updateForecast(e.target.dataset.uid);});

  const Sound={ctx:null,timer:null,step:0,
    init(){if(!this.ctx){try{this.ctx=new(window.AudioContext||window.webkitAudioContext)();}catch{return;}}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});},
    tone(freq,duration,volume=.1,type='sine',delay=0){if(!this.ctx)return;const t=this.ctx.currentTime+delay,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume*settings.volume,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+duration+.02);},
    click(){if(settings.sound)this.tone(700,.09,.08);},hit(){if(settings.sound){this.tone(130,.13,.17,'triangle');this.tone(55,.19,.16,'sine');}},block(){if(settings.sound){this.tone(570,.23,.12);this.tone(850,.25,.06,'sine',.025);}},error(){if(settings.sound)this.tone(180,.15,.09,'triangle');},chime(){if(settings.sound)[523,659,784,1047].forEach((f,i)=>this.tone(f,.65,.13,'sine',i*.1));},
    whoosh(){if(settings.sound){this.tone(180,.16,.06,'triangle');this.tone(620,.12,.04,'triangle',.05);}},
    charge(index=0){if(settings.sound){[220,330,440,660,880].forEach((f,i)=>this.tone(f*(1+index*.08),.5,.1,'sine',i*.11));this.tone(70,1.25,.1,'triangle');}},
    ultimate(index=0){if(settings.sound){this.tone(45,.6,.23,'sine');this.tone(90,.35,.13,'triangle');[523,784,1047+index*100].forEach((f,i)=>this.tone(f,.65,.06,'sine',i*.07));}},
    music(){clearInterval(this.timer);this.timer=null;if(!settings.music||document.hidden)return;this.init();const notes=[261.63,329.63,392,493.88,440,392,329.63,293.66,220,329.63,392,523.25,493.88,392,329.63,293.66];const play=()=>{const f=notes[this.step++%notes.length];this.tone(f,2.3,.07);if(this.step%4===0){this.tone(f/2,4,.05);this.tone(f*1.5,3.5,.025);}};play();this.timer=setInterval(play,1050);}
  };
  async function action(name,el){
    if(busy)return;
    Sound.init();
    switch(name){
      case 'noop':break;
      case 'close':closeModal();break;
      case 'title':closeModal();page='title';render();break;
      case 'save-title':save();closeModal();page='title';render();break;
      case 'continue':engine.load(saved);page='game';selected=null;render();if(settings.music)Sound.music();break;
      case 'new':if(saved&&saved.screen!=='result'){showModal('新しい冒険へ',`<p>いまの冒険を終えて、新しい旅を始めますか？</p><div class="modal-actions">${button('新しい旅を選ぶ','confirm-new','primary')}${button('もどる','close','secondary')}</div>`);}else{closeModal();page='select';render();}break;
      case 'confirm-new':closeModal();page='select';render();break;
      case 'select-hero':{const seed=document.getElementById('seed-input')?.value;heroChoice=el.dataset.id;Sound.click();render();document.getElementById('seed-input').value=seed||'';break;}
      case 'choose-ultimate':{const seed=document.getElementById('seed-input')?.value;ultimateChoice[heroChoice]=el.dataset.id;render();document.getElementById('seed-input').value=seed||'';Sound.click();break;}
      case 'preview-ultimate':await previewUltimate(el.dataset.id,el.dataset.branch,el.dataset.hero);break;
      case 'difficulty':{const seed=document.getElementById('seed-input')?.value;difficultyChoice=el.dataset.id;render();document.getElementById('seed-input').value=seed||'';break;}
      case 'start':if(modeChoice==='ascent'&&!Progress.ascentUnlocked(profile))throw new Error('物語の5ステージをクリアすると解放されます。');engine.newRun(heroChoice,difficultyChoice,document.getElementById('seed-input').value.trim(),ultimateChoice[heroChoice],{mode:modeChoice,rank:Math.min(rankChoice,Progress.maxRank(profile)),costume:profile.equipped[heroChoice],title:profile.title});page='game';save();render();Sound.chime();if(settings.music)Sound.music();break;
      case 'node':await perform(()=>engine.chooseNode(el.dataset.id));break;
      case 'card':cardSelect(el.dataset.uid);break;
      case 'cancel-card':selected=null;render();break;
      case 'target':if(selected)await perform(()=>engine.play(selected,el.dataset.id),true);else{const e=engine.s.battle.enemies.find(e=>e.uid===el.dataset.id);showModal(esc(e.name),`<div class="enemy-inspect">${sprite(e.sprite)}</div>${intentHTML(e)}<p>HP ${e.hp} / ${e.maxHP}</p>${statusHTML(e)}<p class="muted">攻撃カードを選んでから、この敵をクリックすると攻撃できます。</p>`);}break;
      case 'play-self':if(selected&&!engine.needsTarget(engine.s.battle.hand.find(c=>c.uid===selected)))await perform(()=>engine.play(selected),true);break;
      case 'end-turn':await perform(()=>engine.endTurn(),true);break;
      case 'deck':deckModal();break;
      case 'pile':deckModal('deck',el.dataset.id);break;
      case 'codex':deckFilter='all';deckModal('codex');break;
      case 'filter':deckFilter=el.dataset.id;deckModal('codex');break;
      case 'inspect-card':case 'shop-preview':inspectCard(el);break;
      case 'view-map':if(engine.s.screen==='map'){toast('光っている場所を選んで進みましょう。');}else{showModal('冒険のマップ',mapHTML(true),'map-modal');requestAnimationFrame(()=>{const scroll=modal.querySelector('.map-scroll');scroll.scrollTop=Math.max(0,65+(11-engine.s.row)*79-scroll.clientHeight*.6);});}break;
      case 'relics':relicsModal();break;
      case 'wardrobe':wardrobeModal();break;
      case 'cosmetic-hero':heroChoice=el.dataset.id;if(page==='select')render();wardrobeModal();break;
      case 'equip-costume':if(Progress.unlocked(profile,heroChoice,el.dataset.id)){profile.equipped[heroChoice]=el.dataset.id;write(PROFILE,profile);render();wardrobeModal();}break;
      case 'equip-title':if(Progress.titles(profile).some(t=>t.id===el.dataset.id&&t.unlocked)){profile.title=el.dataset.id;write(PROFILE,profile);render();wardrobeModal();}break;
      case 'journey-mode':if(el.dataset.id==='story'||Progress.ascentUnlocked(profile)){modeChoice=el.dataset.id;render();}break;
      case 'retire':await perform(()=>engine.retire());break;
      case 'relic':{const r=D.relics[el.dataset.id];showModal(r.name,`<div class="item-modal-icon">${icon(r.icon)}</div><p>${r.desc}</p><p class="muted">${r.hero?D.heroes[r.hero].name+'専用 · ':''}${engine.relicStatus(el.dataset.id)}。持っているだけで条件に応じて発動します。</p>`);break;}
      case 'potion':potionModal(Number(el.dataset.index));break;
      case 'use-potion':closeModal();await perform(()=>engine.usePotion(el.dataset.index),engine.s.screen==='battle');break;
      case 'discard-potion':closeModal();await perform(()=>engine.discardPotion(el.dataset.index));break;
      case 'reward-card':await perform(()=>engine.selectReward(el.dataset.uid));Sound.chime();break;
      case 'claim-relic':await perform(()=>engine.claimRelic());break;
      case 'claim-potion':await perform(()=>engine.claimPotion());break;
      case 'finish-reward':await perform(()=>engine.finishReward());break;
      case 'boss-relic':await perform(()=>engine.chooseBossRelic(el.dataset.id));Sound.chime();break;
      case 'rest':await perform(()=>engine.rest());Sound.chime();break;
      case 'upgrade':if(!engine.s.deck.some(c=>D.upgradeLevel(c)<2&&!['curse','status'].includes(D.cards[c.id].type))){toast('強化できるカードがありません。休憩してHPを回復しましょう。');}else deckModal('upgrade');break;
      case 'upgrade-card':{const c=engine.s.deck.find(c=>c.uid===Number(el.dataset.uid));if(c.upgraded)showModal('進化の分岐を選ぶ',branchChoicesHTML(c,true),'wide-modal');else{closeModal();await perform(()=>engine.upgradeCard(c.uid));toast('カードを＋に強化しました。');Sound.chime();}break;}
      case 'evolve-card':closeModal();if(await perform(()=>engine.upgradeCard(el.dataset.uid,el.dataset.branch))){toast('カードが分岐進化しました。イラストと演出が変化！');Sound.chime();}break;
      case 'treasure':await perform(()=>engine.collectTreasure());Sound.chime();break;
      case 'event-choice':await perform(()=>engine.eventChoice(el.dataset.index));if(engine.s.room?.removing)deckModal('remove');break;
      case 'event-remove':deckModal('remove');break;
      case 'leave-room':await perform(()=>engine.finishRoom());break;
      case 'buy':if(await perform(()=>engine.buy(el.dataset.kind,el.dataset.index)))toast('買いものをしました。');break;
      case 'shop-remove':deckModal('remove');break;
      case 'remove-confirm':{const c=engine.s.deck.find(c=>c.uid===Number(el.dataset.uid));showModal('このカードを手放す？',`<div class="single-card">${cardHTML(c,{action:'noop'})}</div><div class="modal-actions">${button('削除する','remove-card','primary',`data-uid="${c.uid}"`)}${button('選びなおす','remove-back','secondary')}</div>`);break;}
      case 'remove-back':deckModal('remove');break;
      case 'remove-card':closeModal();await perform(()=>engine.removeCard(el.dataset.uid));toast('カードをデッキから削除しました。');break;
      case 'settings':case 'home-menu':settingsModal();break;
      case 'help':help();break;
      case 'toggle-music':settings.music=!settings.music;write(SETTINGS,settings);Sound.music();render();toast(settings.music?'BGMをオンにしました。':'BGMをオフにしました。');break;
      case 'log':showModal('戦闘ログ',`<ol class="combat-log">${engine.s.battle.log.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`);break;
      case 'history':{const history=read(HISTORY,[]);showModal('冒険の記録',history.length?`<div class="history-list">${history.map(s=>`<div><span class="history-icon ${s.won?'won':''}">${icon(s.won?'crown':'flower')}</span><span><b>${D.heroes[s.hero].name} · ${s.won?'塔をクリア！':s.stats.floors+'階まで到達'}</b><small>${new Date(s.startedAt).toLocaleDateString('ja-JP')} · ${Engine.DIFFICULTIES[s.difficulty].name}</small></span><strong>${s.stats.battles}<small>勝</small></strong></div>`).join('')}</div>`:'<p class="empty-message">まだ冒険の記録はありません。<br>さあ、最初の一歩を。</p>');break;}
      case 'export':{const blob=new Blob([JSON.stringify({...engine.s,progress:profile})],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='BloomSpire-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('冒険の記録を書き出しました。');break;}
    }
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)action(b.dataset.action,b).catch(err=>{busy=false;toast(err.message);});});
  document.addEventListener('change',e=>{if(e.target.id==='ascent-rank'){rankChoice=Number(e.target.value);render();}if(e.target.dataset.setting){const key=e.target.dataset.setting;settings[key]=e.target.type==='checkbox'?e.target.checked:Number(e.target.value);write(SETTINGS,settings);if(key==='music')Sound.music();if(key==='motion'){document.documentElement.classList.toggle('reduced-motion',!settings.motion);if(!settings.motion)FX.skip();}}if(e.target.id==='import-save'){const file=e.target.files?.[0];if(!file)return;if(file.size>2000000){toast('記録ファイルが大きすぎます。');return;}file.text().then(text=>{const next=new Engine(text);showModal('冒険の記録を読み込む',`<p>${D.heroes[next.s.hero].name}・第${next.s.act+1}章の記録を読み込みます。いまの記録は置き換わります。</p><div class="modal-actions">${button('読み込む','confirm-import','primary')}${button('キャンセル','close','secondary')}</div>`);modal.querySelector('[data-action="confirm-import"]').addEventListener('click',()=>{engine=next;heroChoice=next.s.hero;profile=Progress.merge(profile,next.s.progress);delete engine.s.progress;save();page='game';closeModal();render();toast('冒険の記録を読み込みました。');},{once:true});}).catch(()=>toast('この記録は読み込めませんでした。'));}});
  document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(modal.open)return;if(busy)return;if(e.key==='Escape'){selected=null;render();return;}if(page!=='game'||busy)return;const s=engine.s;if(e.key.toLowerCase()==='d'){e.preventDefault();deckModal();}if(e.key.toLowerCase()==='m'){e.preventDefault();action('view-map',{});}if(s.screen==='battle'){if(e.code==='Space'){e.preventDefault();action('end-turn',{});}if(/^[1-9]$/.test(e.key)){e.preventDefault();const c=s.battle.hand[Number(e.key)-1];if(c)cardSelect(c.uid);}if(e.key==='Enter'&&selected){const alive=s.battle.enemies.filter(e=>e.hp>0);if(alive.length===1)perform(()=>engine.play(selected,alive[0].uid),true);}}});
  document.addEventListener('dragstart',e=>{const card=e.target.closest('.hand .game-card');if(!card||busy){e.preventDefault();return;}cardDrag=Number(card.dataset.uid);e.dataTransfer.setData('text/plain',String(cardDrag));e.dataTransfer.effectAllowed='move';app.classList.add('dragging-card');});
  document.addEventListener('dragover',e=>{if(cardDrag!==null){e.preventDefault();e.dataTransfer.dropEffect='move';}});
  document.addEventListener('drop',e=>{e.preventDefault();if(cardDrag===null||busy)return;const c=engine.s.battle.hand.find(c=>c.uid===cardDrag);const target=e.target.closest('[data-entity^="enemy"]');const uid=cardDrag;cardDrag=null;app.classList.remove('dragging-card');if(c&&(!engine.needsTarget(c)||target))perform(()=>engine.play(uid,target?.dataset.entity),true);});
  document.addEventListener('dragend',()=>{cardDrag=null;app.classList.remove('dragging-card');});
  modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){FX.skip();save();clearInterval(Sound.timer);Sound.timer=null;}else if(settings.music&&Sound.ctx)Sound.music();});
  window.addEventListener('pagehide',()=>save());
  const modelContext=document.modelContext;
  if(modelContext?.registerTool){try{Promise.resolve(modelContext.registerTool({name:'read_bloom_spire_game',title:'冒険の状態を見る',description:'現在の冒険者、画面、HP、戦闘の手札・敵の行動予告を読み取る。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){const s=engine.s;return s?{screen:page==='game'?s.screen:page,hero:D.heroes[s.hero].name,hp:s.hp,maxHP:s.maxHP,act:s.act+1,floor:s.row+1,gold:s.gold,energy:s.battle?.energy,hand:s.battle?.hand.map(c=>({uid:c.uid,name:D.getCard(c,s.hero).name,cost:D.getCard(c).cost,description:D.describe(c)})),enemies:s.battle?.enemies.filter(e=>e.hp>0).map(e=>({id:e.uid,name:e.name,hp:e.hp,intent:engine.intent(e)}))}:{screen:page};}})).catch(()=>{});}catch{}}
  render();
})();
